      if (pageA) await ensureSessionReady(pageA)

      const scriptedBefore = pageA ? await evalIn(pageA, 'document.documentElement.getAttribute("data-ext-scripted")') : null

      let crossOutcome = '(대상 없음 — ownerB 또는 localIdA 미확보)'
