    // ---- X2 콘텐츠 스크립트 주입 ----
    check('X2', '콘텐츠 스크립트가 페이지에 주입·실행된다',
      state1.injected === 'yes' && String(state1.mark) === '확장이 바꿈',
      `주입 표식=${state1.injected} · 본문 변경="${state1.mark}"`)

    // ---- X6/X7: modifyHeaders (임무 37) ----
    {
