        + ` · tabs.get(id).url=${ownerGetUrl ?? '(없음)'}`
        + ` · 다른 세션 누출 ${foreignLeak}건 · 다른 세션 응답=${JSON.stringify(foreignGets).slice(0, 120)}`
        + ` · SW별 탭수=[${seenBySw.map((s) => s.length).join(',')}]`)

