        const liveMax = Math.max(0, ...okIds, ...(sweep.other ?? []).map((s) => Number(String(s).split(':')[0]) || 0))
        x25.note = `훑은 id 1~${MAXID} · 주입 성공 ${okIds.length}개(최대 살아있는 id ${liveMax})`
