    // ---- X1 declarativeNetRequest 차단 ----
    pages.resetHits()
    const { tabId: t1, page: p1, url: x1Url } = await openPage('?x1')
    const state1 = p1 ? {
      adLoaded: await evalIn(p1, 'window.__adLoaded === true'),
