            + `.then((t) => JSON.stringify({ id: t && t.id, url: String((t && t.url) || '') }))`
            + `.catch((e) => JSON.stringify({ err: String(e && e.message || e) }))`, true) ?? 'null')
          if (i === ownerIdx) {
            ownerGetUrl = got?.url ?? null
