    try { p1?.close() } catch { /* ignore */ }

    // 확장 id 를 여기서 한 번만 정한다(X5 이후 모든 생애주기 검사가 이 값을 쓴다).
    // 앱이 보고하는 id 는 디렉터리 이름이고, 그것이 곧 확장 ID 여야 한다(위 writeTestExtension 주석).
